/* Выбрать описания takeaway и prepared блюд с датой best before 2018-11-10 */
SELECT DISTINCT
    "m"."description"
FROM "meals" AS "m"
WHERE (
        LOWER("m"."mealtype") = 'takeaway'
        AND TO_DATE("m"."bestbefore", 'DD.MM.YYYY') = DATE '2018-11-10'
    )
   OR (
        LOWER("m"."mealtype") = 'prepared'
        AND TO_DATE("m"."bestbefore", 'DD.MM.YYYY') = DATE '2018-11-10'
    );

SELECT
    /* Вывести описание takeaway и описание блюда с датой best before 10.11.2018 */
    "m"."mealtype" AS "takeaway_description",
    "m"."description" AS "prepared_meal_description"
FROM "meals" AS "m"
WHERE TO_DATE("m"."bestbefore"::TEXT, 'DD.MM.YYYY') = TO_DATE('10.11.2018', 'DD.MM.YYYY');

/* List all the rooms that cost 150 per night and are either a family suite or single room */
SELECT
  "a"."roomnumber"
FROM "accommodations" AS "a"
WHERE "a"."pricepernight" = 150
  AND (
    LOWER("a"."typeofaccomodation") = LOWER('family suite')
    OR LOWER("a"."typeofaccomodation") = LOWER('single room')
  );

/* Минимальный и предпочтительный опыт для позиции с максимальной зарплатой */
SELECT
  "j"."minimum_years",
  "j"."preferred_years"
FROM "jobs" AS "j"
WHERE "j"."salary" = (
  SELECT MAX("j2"."salary")
  FROM "jobs" AS "j2"
)
LIMIT 1;

/* Preferred years of experience for the open position with the greatest salary */
SELECT "j"."preferred_years"
FROM "jobs" AS "j"
WHERE "j"."salary" = (
  SELECT MAX("j2"."salary")
  FROM "jobs" AS "j2"
);

/* Минимальные годы опыта для вакансии с максимальной зарплатой */
SELECT "j"."minimum_years"
FROM "jobs" AS "j"
WHERE "j"."salary" = (
    SELECT MAX("j2"."salary")
    FROM "jobs" AS "j2"
)
LIMIT 1;

SELECT
  /* Требуемый уровень образования для должности AI Researcher */
  "degree_level"
FROM "degrees" AS d
WHERE LOWER(TRIM(d."job_post")) = LOWER(TRIM('AI Researcher'));

SELECT
  /* Required certification for the AI Researcher job */
  "d"."certification"
FROM "degrees" AS "d"
WHERE LOWER(TRIM("d"."job_post")) = LOWER(TRIM('AI Researcher'));

/* Required degree level and certification for AI Researcher */
SELECT
  "d"."degree_level",
  "d"."certification"
FROM "degrees" AS "d"
WHERE LOWER(TRIM("d"."job_post")) = LOWER('AI Researcher');

/* Find the marketing office location */
SELECT
  "d"."building" AS "office_location"
FROM "departments" AS "d"
WHERE LOWER("d"."name") = LOWER('marketing');

/* List all executive chefs in alphabetical order by their name */
SELECT
  "ec"."chef_id",
  "ec"."full_name"
FROM "executive_chef" AS "ec"
ORDER BY "ec"."full_name" ASC;

/* Список всех су-шефов в алфавитном порядке по имени */
SELECT
    "sc"."sous_id",
    "sc"."full_name"
FROM "sous_chef" AS "sc"
ORDER BY "sc"."full_name" ASC;
